def table(header, rows, caption=None, cls='', note=None, widths=None):
    h = ('<p class="cap">' + caption + '</p>') if caption else ''
    h += '<table class="tab ' + cls + '">'
    h += '<tr>' + ''.join('<th>' + x + '</th>' for x in header) + '</tr>'
    for row in rows: h += '<tr>' + ''.join('<td>' + str(x) + '</td>' for x in row) + '</tr>'
    h += '</table>'
    if note: h += '<p class="tabnote">' + note + '</p>'
    return h
